from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.ta_matchers.matchers import Any, Contains, Omit
from taf.ul.ettf.pdml_parser.parser import Enum
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageDetail


SUBPRIOS = {
    'oDot2': 0,
    'oDot4': 1,
    'oDot8': 3
}


def freq_priority_eutra(carrier_freq=None, priority=None):
    return Any({
        "FreqPriorityEUTRA": Any({
            "carrierFreq": carrier_freq,
            "cellReselectionPriority": priority
        })
    })


def freq_priority_eutra_v1310(subpriority=None):
    return Any({
        "FreqPriorityEUTRA-v1310": Any({
            "cellReselectionSubPriority-r13": Enum(*subpriority) if subpriority else Omit()
        })
    })


def freq_priority_utra_fdd(carrier_freq=None, priority=None):
    return Any({
        "FreqPriorityUTRA-FDD": Any({
            "carrierFreq": carrier_freq,
            "cellReselectionPriority": priority
        })
    })


def freq_priority_nr_r15(carrier_freq=None, priority=None, subpriority=None):
    return Any({
        "FreqPriorityNR-r15": Any({
            "carrierFreq-r15": carrier_freq,
            "cellReselectionSubPriority-r15": Enum(*subpriority) if subpriority else Omit(),
            "cellReselectionPriority-r15": priority
        })
    })


class immci(ExpectationsManager):
    @typed(carrier_freq=int, priority=int)
    def with_freq_priority_eutra(self, carrier_freq, priority):
        self.append_expectation(MessageDetail('freqPriorityListEUTRA', freq_priority_eutra(carrier_freq, priority), Contains))

    def with_freq_priority_eutra_v1310(self):
        self.append_expectation(MessageDetail('freqPriorityListEUTRA-v1310', freq_priority_eutra_v1310(), Contains))

    @typed(subpriority=str)
    def with_freq_priority_eutra_v1310_with_subpriority(self, subpriority):
        self.append_expectation(MessageDetail('freqPriorityListEUTRA-v1310',
                                freq_priority_eutra_v1310(subpriority=(subpriority, SUBPRIOS[subpriority])), Contains))

    @typed(carrier_freq=int, priority=int)
    def with_freq_priority_utra_fdd(self, carrier_freq, priority):
        self.append_expectation(MessageDetail('freqPriorityListUTRA-FDD', freq_priority_utra_fdd(carrier_freq, priority), Contains))

    @typed(carrier_freq=int, priority=int, subpriority=str)
    def with_freq_priority_nr_r15(self, carrier_freq, priority, subpriority=None):
        self.append_expectation(MessageDetail('freqPriorityListNR-r15', freq_priority_nr_r15(carrier_freq,
                                priority, (subpriority, SUBPRIOS[subpriority]) if subpriority else None), Contains))
